import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788117098000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>WIKIJS_READ_ONLY</code> is set, and it is a write tool.</li><li><code>WIKIJS_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>WIKIJS_DENY_TOOLS</code> names it, possibly through a prefix such as <code>delete_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot; — the same as a write tool under read-only. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><h2 id="search-finds-nothing-but-the-words-are-definitely-on-the-page" tabindex="-1">Search finds nothing, but the words are definitely on the page <a class="header-anchor" href="#search-finds-nothing-but-the-words-are-definitely-on-the-page" aria-label="Permalink to “Search finds nothing, but the words are definitely on the page”">​</a></h2><p>Wiki.js&#39; default search engine is <strong>&quot;Database - Basic&quot;</strong>, and it indexes page titles and descriptions only. Text written <em>inside</em> a page is not searchable at all — the engine simply has no index of it, so <code>search_pages</code> correctly returns zero hits.</p><p><code>search_pages</code> reports which engine is active, so you can tell at a glance. Two ways forward:</p><ul><li><strong><code>grep_pages</code></strong> fetches pages and matches their text locally. Slower — one request per page — but it finds things. Narrow it with <code>path_prefix</code>, <code>tags</code> or <code>locale</code>.</li><li><strong>Switch the engine.</strong> Administration → Search Engine → Database - PostgreSQL (or Elasticsearch), then run <code>rebuild_search_index</code> <strong>once</strong>. A new engine starts empty, and until it is rebuilt search silently returns nothing at all, which looks exactly like a broken installation.</li></ul><h2 id="update-page-refuses-to-write-and-talks-about-a-conflict" tabindex="-1"><code>update_page</code> refuses to write and talks about a conflict <a class="header-anchor" href="#update-page-refuses-to-write-and-talks-about-a-conflict" aria-label="Permalink to “update_page refuses to write and talks about a conflict”">​</a></h2><p>Somebody saved the page between your <code>get_page</code> and your <code>update_page</code> — from the web editor, or another client. Writing now would discard their edit without either of you noticing, so the server stops.</p><ul><li><code>get_page_conflict</code> shows the newer version, with who saved it and when.</li><li>Re-read the page with <code>get_page</code> and redo your change on top of it.</li><li><code>force: true</code> overwrites their edit deliberately.</li></ul><p>The comparison is against the moment <strong>you</strong> read the page, not the moment the handler read it — the latter is a millisecond old and can never fail, which would be protection in appearance only.</p><h2 id="everything-answers-not-found-but-the-pages-are-there" tabindex="-1">Everything answers &quot;not found&quot;, but the pages are there <a class="header-anchor" href="#everything-answers-not-found-but-the-pages-are-there" aria-label="Permalink to “Everything answers &quot;not found&quot;, but the pages are there”">​</a></h2><p>The locale. Wiki.js treats it as part of a page&#39;s identity, and this server defaults to <code>en</code>. On a wiki set up in German every path lives under <code>de</code>, so <code>docs/setup</code> genuinely does not exist. Set <code>WIKIJS_LOCALE=de</code>, or pass <code>locale</code> per call; <code>list_locales</code> shows what is installed.</p><h2 id="a-page-s-metadata-comes-back-but-its-text-does-not" tabindex="-1">A page&#39;s metadata comes back but its text does not <a class="header-anchor" href="#a-page-s-metadata-comes-back-but-its-text-does-not" aria-label="Permalink to “A page&#39;s metadata comes back but its text does not”">​</a></h2><p>The API key lacks <code>read:source</code>, which Wiki.js keeps separate from <code>read:pages</code>. The result says so rather than pretending the page is empty. Add the scope to the key&#39;s group, or use <code>mode: &quot;rendered&quot;</code>, which sometimes remains available.</p><h2 id="everything-fails-with-an-html-error-or-answered-graphql-with-text-html" tabindex="-1">Everything fails with an HTML error, or &quot;answered /graphql with text/html&quot; <a class="header-anchor" href="#everything-fails-with-an-html-error-or-answered-graphql-with-text-html" aria-label="Permalink to “Everything fails with an HTML error, or &quot;answered /graphql with text/html&quot;”">​</a></h2><p><code>WIKIJS_URL</code> is not pointing at a Wiki.js server, or a proxy answered instead. Wiki.js serves its web UI from the same origin as <code>/graphql</code> and falls back to it for anything it does not route, so a wrong URL replies <strong>200 with a web page</strong> rather than a 404. <code>get_site_info</code> is the quickest check.</p><h2 id="creating-comments-fails-with-too-many-requests" tabindex="-1">Creating comments fails with &quot;Too many requests&quot; <a class="header-anchor" href="#creating-comments-fails-with-too-many-requests" aria-label="Permalink to “Creating comments fails with &quot;Too many requests&quot;”">​</a></h2><p>Wiki.js rate-limits comment creation to roughly one per second, although its documentation says the API is not throttled at all. Wait a moment and call again.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};